/** [FS-SEND-CHANCE-STICKER-FN] 这一轮能不能发表情：按 stickers.sendChance 掷骰子（同一条回复只掷一次）。 */
export function stickerSendAllowed(cfg = {}) {
	const n = Number(cfg?.sendChance);
	const chance = Number.isFinite(n) ? Math.min(1, Math.max(0, n)) : 0.15;
	return Math.random() < chance;
}

